import express from 'express';
import { z } from 'zod';

class HttpError extends Error {
  constructor(status, message) { super(message); this.status = status; }
}
const butuhKunci = (req, res, next) => {
  if (req.get('x-api-key') !== 'kunci-toko') throw new HttpError(401, 'Kunci API salah');
  next();
};
const validasi = (skema) => (req, res, next) => {
  const hasil = skema.safeParse(req.body);
  if (!hasil.success) {
    return res.status(400).json({ error: 'Data tidak valid', detail: hasil.error.issues.map((i) => i.path.join('.')) });
  }
  req.body = hasil.data;
  next();
};
const MenuBaru = z.object({ nama: z.string().min(2), harga: z.number().int().positive() });

const menu = [];
const app = express();
app.use((req, res, next) => {
  res.on('finish', () => console.log('LOG', req.method, req.originalUrl, res.statusCode));
  next();
});
app.use(express.json());
app.get('/menu', (req, res) => res.json(menu));
app.post('/menu', butuhKunci, validasi(MenuBaru), (req, res) => {
  const baru = { id: menu.length + 1, ...req.body };
  menu.push(baru);
  res.status(201).json(baru);
});
app.use((req, res) => res.status(404).json({ error: 'Jalur tidak ditemukan' }));
app.use((err, req, res, next) => {
  if (err.status && err.status < 500) return res.status(err.status).json({ error: err.message });
  res.status(500).json({ error: 'Terjadi kesalahan di server' });
});
const server = app.listen(3000);

const kirim = (kunci, body) => fetch('http://localhost:3000/menu', {
  method: 'POST', headers: { 'Content-Type': 'application/json', 'X-API-Key': kunci }, body: JSON.stringify(body),
});
await kirim('salah', { nama: 'Teh', harga: 12000 });
console.log((await (await kirim('kunci-toko', { nama: 'T', harga: 'gratis' })).json()).detail);
await kirim('kunci-toko', { nama: 'Teh Tarik', harga: 12000, admin: true });
console.log(await (await fetch('http://localhost:3000/menu')).json());
server.close();

