import express from 'express';
import { z } from 'zod';
const Menu = z.object({ nama: z.string().min(2), harga: z.number().positive() });
function validasi(skema) {
  return (req, res, next) => {
    const hasil = skema.safeParse(req.body);
    if (!hasil.success) return res.status(400).json({ error: 'Data tidak valid' });
    req.body = hasil.data;
    next();
  };
}
const menu = [];
const app = express();
app.use(express.json());
app.post('/menu', validasi(Menu), (req, res) => {
  menu.push(req.body);
  res.status(201).json(req.body);
});
app.use((err, req, res, next) => res.status(err.status ?? 500).json({ error: err.message }));
const server = app.listen(3000);
const kirim = (body) => fetch('http://localhost:3000/menu', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
const r = await kirim({ nama: 'Kopi', harga: 18000 });
console.log(r.status, await r.json());
const r2 = await kirim({ nama: 'K', harga: 0 });
console.log(r2.status, await r2.json());
server.close();

