import express from 'express';
import { z } from 'zod';
const app = express();
function validasiQuery(skema) {
  return (req, res, next) => {
    if (!skema.safeParse(req.query).success) return res.sendStatus(400);
    next();
  };
}
app.get('/menu', validasiQuery(z.object({ halaman: z.coerce.number().int().min(1) })), (req, res) => res.send('ok'));
const server = app.listen(3000);
const a = await fetch('http://localhost:3000/menu?halaman=0');
const b = await fetch('http://localhost:3000/menu?halaman=2');
console.log(a.status, b.status);
server.close();
